/**
 * Archiving a project freezes its issues, including the ones left live when it
 * was archived. The project is read on every call rather than trusted from the
 * caller, so restoring the project lifts the freeze with nothing else to undo.
 * Call after the issue's own archive check, so an archived issue still reports
 * itself first.
 */
export async function assertIssueNotFrozen(issue: Issue): Promise<void> {
  const project = requireFound(
    await projectRepo.findProjectById(issue.orgId, issue.projectId),
    "Project",
    issue.projectId,
  );
  assertNotArchived("Project", project.id, project);
}

