/**
 * An archived project without its issues freezes them. Every write to such an
 * issue or its sub-resources refuses with AlreadyArchivedError before changing
 * anything or publishing an event; reads keep working; restoring the project
 * lifts the freeze.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Comment } from "@/types/comment";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Issue, IssueAttachment } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let issue: Issue;
let comment: Comment;
let attachment: IssueAttachment;
let staleIssue: Issue;
let staleComment: Comment;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** Watches every event a frozen write could publish; the check returns what fired. */
function watchWrites(): () => unknown[] {
  const seen = [
    capture("issue.updated"),
    capture("issue.status_changed"),
    capture("issue.assigned"),
    capture("issue.archived"),
    capture("comment.created"),
    capture("comment.deleted"),
  ];
  return () => seen.flat();
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("frozen", "growth");
  const { org, project, actors } = tenant;

  issue = await issueService.createIssue(
    actors.member,
    issueInput(org.id, project.id, { title: "Frozen target" }),
  );
  comment = await commentService.createComment(actors.member, {
    orgId: org.id,
    issueId: issue.id,
    body: "Posted before the freeze",
    parentId: null,
    mentionedUserIds: [],
  });
  attachment = await attachmentService.addAttachment(actors.member, {
    orgId: org.id,
    issueId: issue.id,
    filename: "spec.pdf",
    contentType: "application/pdf",
    sizeBytes: 2048,
  });

  staleIssue = await issueService.createIssue(
    actors.member,
    issueInput(org.id, project.id, { title: "Archived before the freeze" }),
  );
  await issueService.archiveIssue(actors.member, org.id, staleIssue.id);

  const doomedComment = await commentService.createComment(actors.member, {
    orgId: org.id,
    issueId: issue.id,
    body: "Deleted before the freeze",
    parentId: null,
    mentionedUserIds: [],
  });
  staleComment = await commentService.deleteComment(actors.member, {
    orgId: org.id,
    commentId: doomedComment.id,
  });

  await projectService.archiveProject(actors.admin, {
    orgId: org.id,
    projectId: project.id,
    archiveIssues: false,
  });
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("writes to a frozen issue", () => {
  it("leaves the issue itself live", async () => {
    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.archivedAt).toBeNull();
  });

  it("refuses field edits without changing the row or publishing", async () => {
    const published = watchWrites();

    await expect(
      issueService.updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Renamed while frozen",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.title).toBe("Frozen target");
    expect(published()).toEqual([]);
  });

  it("refuses status changes, including board moves", async () => {
    const published = watchWrites();

    await expect(
      issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        status: "in_progress",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      issueService.moveIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toStatus: "done",
        toIndex: 0,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.status).toBe("backlog");
    expect(published()).toEqual([]);
  });

  it("refuses assigning and un-assigning", async () => {
    const published = watchWrites();

    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: null,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.assigneeId).toBeNull();
    expect(published()).toEqual([]);
  });

  it("refuses to archive the issue", async () => {
    const published = watchWrites();

    await expect(
      issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.archivedAt).toBeNull();
    expect(published()).toEqual([]);
  });

  it("refuses new comments", async () => {
    const before = await commentRepo.countComments(tenant.org.id, issue.id);
    const published = watchWrites();

    await expect(
      commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "Too late",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      commentRepo.countComments(tenant.org.id, issue.id),
    ).resolves.toBe(before);
    expect(published()).toEqual([]);
  });

  it("refuses edits and deletes of an existing comment", async () => {
    const published = watchWrites();

    await expect(
      commentService.updateComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "Edited while frozen",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      commentService.deleteComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const stored = await commentRepo.findCommentById(tenant.org.id, comment.id);
    expect(stored?.body).toBe("Posted before the freeze");
    expect(stored?.archivedAt).toBeNull();
    expect(published()).toEqual([]);
  });

  it("refuses attachments being added and removed", async () => {
    const published = watchWrites();

    await expect(
      attachmentService.addAttachment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        filename: "late.pdf",
        contentType: "application/pdf",
        sizeBytes: 1024,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      attachmentService.removeAttachment(tenant.actors.member, {
        orgId: tenant.org.id,
        attachmentId: attachment.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const stored = await attachmentService.listAttachments(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );
    expect(stored.map((row) => row.id)).toEqual([attachment.id]);
    expect(published()).toEqual([]);
  });

  it("keeps the permission check ahead of the freeze", async () => {
    await expect(
      issueService.updateIssue(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Viewer edit",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("reports an archived issue or comment as itself, not as the project", async () => {
    await expect(
      issueService.updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: staleIssue.id,
        title: "Still archived",
      }),
    ).rejects.toThrow(/^Issue /);

    await expect(
      commentService.deleteComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: staleComment.id,
      }),
    ).rejects.toThrow(/^Comment /);
  });

  it("names the project as the reason for a frozen issue", async () => {
    const error = await issueService
      .updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Still frozen",
      })
      .catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(AlreadyArchivedError);
    expect((error as AlreadyArchivedError).entity).toBe("Project");
